SELECT "nct", "author", "year", "pubmed_id", "trial_name", "treatment_regimen", "name_of_ici", "class_of_ici", "monotherapy_combination", "type_of_combination", "control_regimen", "type_of_control", "cancer_type", "trial_phase" FROM public."clinical_trials" WHERE "trial_phase" = 'Phase 3' AND "cancer_type" = 'Non-Small Cell Lung' AND "class_of_ici" ILIKE '%PD1%' OR "class_of_ici" ILIKE '%CTLA-4%' AND "is_pd_l1_positivity_inclusion_criteria" = true;